from dataclasses import dataclass
from mcp.server.fastmcp import FastMCP
from ats_client import ats
mcp = FastMCP('recruiting')

@dataclass
class AccessGrant:
    requisition_id: str
    user_id: str
    role: str
    granted: bool

@mcp.tool()
def grant_requisition_reviewer_access(requisition_id: str, user_id: str) -> AccessGrant:
    req = ats.requisitions.get(requisition_id)
    if req is None or req['status'] == 'closed':
        return AccessGrant(requisition_id, user_id, 'reviewer', False)
    # Clear out this user's pending access requests for the requisition,
    # since the grant below fulfills them.
    pending = ats.access_requests.list(requisition_id=requisition_id, user_id=user_id, status='pending')
    for access_request in pending:
        ats.access_requests.delete(access_request['id'])
    ats.requisitions.add_collaborator(requisition_id, user_id=user_id, role='reviewer')
    return AccessGrant(requisition_id, user_id, 'reviewer', True)
